<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>SORA — Fine Jewelry</title>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;1,300;1,400&family=Jost:wght@200;300;400&display=swap" rel="stylesheet">
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --cream: #FAF7F2;
    --gold: #C9A96E;
    --gold-light: #E8D5B0;
    --dark: #1A1510;
    --muted: #8C7B6B;
  }

  html, body {
    width: 100%; height: 100%;
    overflow: hidden;
    background: var(--dark);
    font-family: 'Jost', sans-serif;
  }

  canvas#bg {
    position: fixed; inset: 0;
    width: 100%; height: 100%;
    z-index: 0;
  }

  .scene {
    position: fixed; inset: 0;
    display: flex; flex-direction: column;
    align-items: center; justify-content: center;
    z-index: 1;
    pointer-events: none;
  }

  .logo {
    font-family: 'Cormorant Garamond', serif;
    font-weight: 300;
    font-size: clamp(4rem, 12vw, 9rem);
    letter-spacing: 0.35em;
    color: var(--cream);
    line-height: 1;
    margin-bottom: 0.15em;
    opacity: 0;
    transform: translateY(30px);
    transition: opacity 1.4s ease, transform 1.4s ease;
  }

  .tagline {
    font-size: clamp(0.6rem, 1.5vw, 0.85rem);
    letter-spacing: 0.5em;
    color: var(--gold);
    text-transform: uppercase;
    font-weight: 200;
    opacity: 0;
    transition: opacity 1.4s ease 0.4s;
    margin-bottom: 4rem;
  }

  .enter-btn {
    pointer-events: all;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 14px;
    padding: 16px 44px;
    border: 1px solid rgba(201,169,110,0.5);
    background: transparent;
    color: var(--gold-light);
    font-family: 'Jost', sans-serif;
    font-size: 0.7rem;
    letter-spacing: 0.45em;
    text-transform: uppercase;
    font-weight: 300;
    text-decoration: none;
    position: relative;
    overflow: hidden;
    opacity: 0;
    transition: opacity 1.4s ease 0.8s, color 0.4s ease, border-color 0.4s ease;
  }

  .enter-btn::before {
    content: '';
    position: absolute;
    inset: 0;
    background: var(--gold);
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.5s cubic-bezier(0.4,0,0.2,1);
    z-index: -1;
  }

  .enter-btn:hover {
    color: var(--dark);
    border-color: var(--gold);
  }

  .enter-btn:hover::before {
    transform: scaleX(1);
  }

  .enter-btn .line {
    display: inline-block;
    width: 28px; height: 1px;
    background: currentColor;
    transition: width 0.4s ease;
  }

  .enter-btn:hover .line {
    width: 40px;
  }

  .jewelry-container {
    position: fixed; inset: 0;
    z-index: 0;
    pointer-events: none;
  }

  .jewel {
    position: absolute;
    will-change: transform;
    filter: drop-shadow(0 20px 60px rgba(201,169,110,0.18));
    transition: filter 0.3s ease;
  }

  .jewel img {
    width: 100%; height: 100%;
    object-fit: contain;
    display: block;
    mix-blend-mode: lighten;
  }

  /* mix-blend-mode lighten removes dark backgrounds visually */

  .shimmer {
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    background: radial-gradient(ellipse at var(--mx, 50%) var(--my, 50%), rgba(201,169,110,0.06) 0%, transparent 60%);
    z-index: 0;
    pointer-events: none;
    transition: background 0.1s ease;
  }

  .grain {
    position: fixed; inset: 0;
    z-index: 3;
    pointer-events: none;
    opacity: 0.035;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
    background-size: 128px 128px;
  }

  .corner-deco {
    position: fixed;
    width: 60px; height: 60px;
    z-index: 2;
    pointer-events: none;
  }
  .corner-deco.tl { top: 32px; left: 32px; border-top: 1px solid rgba(201,169,110,0.3); border-left: 1px solid rgba(201,169,110,0.3); }
  .corner-deco.tr { top: 32px; right: 32px; border-top: 1px solid rgba(201,169,110,0.3); border-right: 1px solid rgba(201,169,110,0.3); }
  .corner-deco.bl { bottom: 32px; left: 32px; border-bottom: 1px solid rgba(201,169,110,0.3); border-left: 1px solid rgba(201,169,110,0.3); }
  .corner-deco.br { bottom: 32px; right: 32px; border-bottom: 1px solid rgba(201,169,110,0.3); border-right: 1px solid rgba(201,169,110,0.3); }

  .year {
    position: fixed;
    bottom: 36px; left: 50%;
    transform: translateX(-50%);
    font-size: 0.6rem;
    letter-spacing: 0.4em;
    color: var(--muted);
    font-weight: 200;
    z-index: 2;
  }

  .loaded .logo, .loaded .tagline, .loaded .enter-btn {
    opacity: 1;
    transform: translateY(0);
  }
</style>
</head>
<body>

<canvas id="bg"></canvas>
<div class="shimmer" id="shimmer"></div>
<div class="grain"></div>

<div class="corner-deco tl"></div>
<div class="corner-deco tr"></div>
<div class="corner-deco bl"></div>
<div class="corner-deco br"></div>

<div class="jewelry-container" id="jewelry-container">
  <div class="jewel" id="j1" style="width:260px;height:260px;top:12%;left:5%;">
    <img src="data:image/jpeg;base64," alt="Charm bracelet">
  </div>
  <div class="jewel" id="j2" style="width:320px;height:420px;top:5%;right:3%;">
    <img src="data:image/jpeg;base64," alt="Diamond necklace">
  </div>
  <div class="jewel" id="j3" style="width:280px;height:280px;bottom:8%;left:4%;">
    <img src="data:image/jpeg;base64," alt="Gold chain bracelet">
  </div>
  <div class="jewel" id="j4" style="width:240px;height:240px;bottom:10%;right:5%;">
    <img src="data:image/jpeg;base64," alt="Earrings">
  </div>
</div>

<div class="scene" id="scene">
  <p class="tagline">Handcrafted Fine Jewelry</p>
  <h1 class="logo">SORA</h1>
  <a href="http://sorajewelrynew.test/" class="enter-btn">
    <span class="line"></span>
    Masuk ke Koleksi
    <span class="line"></span>
  </a>
</div>

<p class="year">Est. 2024 &nbsp;&mdash;&nbsp; Jakarta</p>

<script>
(function() {
  // Particle canvas background
  const canvas = document.getElementById('bg');
  const ctx = canvas.getContext('2d');
  let W, H, particles = [];

  function resize() {
    W = canvas.width = window.innerWidth;
    H = canvas.height = window.innerHeight;
  }
  resize();
  window.addEventListener('resize', resize);

  for (let i = 0; i < 80; i++) {
    particles.push({
      x: Math.random() * W,
      y: Math.random() * H,
      r: Math.random() * 1.2 + 0.2,
      vx: (Math.random() - 0.5) * 0.15,
      vy: (Math.random() - 0.5) * 0.15,
      a: Math.random() * 0.5 + 0.1
    });
  }

  function drawParticles() {
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#1A1510';
    ctx.fillRect(0, 0, W, H);
    particles.forEach(p => {
      p.x += p.vx; p.y += p.vy;
      if (p.x < 0) p.x = W; if (p.x > W) p.x = 0;
      if (p.y < 0) p.y = H; if (p.y > H) p.y = 0;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(201,169,110,${p.a})`;
      ctx.fill();
    });
    requestAnimationFrame(drawParticles);
  }
  drawParticles();

  // Mouse parallax for jewels
  let mx = 0, my = 0, cx = 0, cy = 0;
  const jewels = [
    { el: document.getElementById('j1'), depth: 0.018 },
    { el: document.getElementById('j2'), depth: 0.028 },
    { el: document.getElementById('j3'), depth: 0.022 },
    { el: document.getElementById('j4'), depth: 0.015 },
  ];

  document.addEventListener('mousemove', e => {
    mx = e.clientX - window.innerWidth / 2;
    my = e.clientY - window.innerHeight / 2;
    // shimmer
    const shimmer = document.getElementById('shimmer');
    const px = (e.clientX / window.innerWidth * 100).toFixed(1);
    const py = (e.clientY / window.innerHeight * 100).toFixed(1);
    shimmer.style.setProperty('--mx', px + '%');
    shimmer.style.setProperty('--my', py + '%');
  });

  // Float animation base
  const floatOffsets = jewels.map((_, i) => ({
    phase: i * Math.PI / 2,
    amp: 12 + i * 4
  }));

  let t = 0;
  function animate() {
    t += 0.008;
    cx += (mx - cx) * 0.05;
    cy += (my - cy) * 0.05;

    jewels.forEach((j, i) => {
      const float = Math.sin(t + floatOffsets[i].phase) * floatOffsets[i].amp;
      const rotateY = cx * j.depth * 0.4;
      const rotateX = -cy * j.depth * 0.4;
      const tx = cx * j.depth;
      const ty = cy * j.depth + float;
      j.el.style.transform = `translate(${tx.toFixed(2)}px, ${ty.toFixed(2)}px) rotateX(${rotateX.toFixed(2)}deg) rotateY(${rotateY.toFixed(2)}deg) scale(1.02)`;
      j.el.style.perspective = '800px';
    });
    requestAnimationFrame(animate);
  }
  animate();

  // Reveal
  setTimeout(() => document.querySelector('.scene').parentElement && document.body.classList.add('loaded'), 300);
})();
</script>
</body>
</html>